func process() async -> [String] {
    await withTaskGroup(of: String.self) {
        group in
        for item in ["B", "A", "C"] {
            group.addTask { item }
        }
        var list: [String] = []
        for await res in group {
            list.append(res)
        }
        return list.sorted()
    }
}

let sorted = await process()
print(sorted.joined(separator: "-"))

