func doubleAll(_ nums: [Int]) async -> [Int] {
    await withTaskGroup(of: Int.self) {
        group in
        for n in nums {
            group.addTask { n * 2 }
        }
        var out: [Int] = []
        for await val in group {
            out.append(val)
        }
        return out.sorted()
    }
}

let res = await doubleAll([3, 1, 2])
print(res)

