func squareAll(_ values: [Int]) async -> [Int] {
    await withTaskGroup(of: Int.self) { group in
        for x in values {
            group.addTask { x * x }
        }
        var out: [Int] = []
        for await val in group {
            out.append(val)
        }
        return out.sorted()
    }
}

let result = await squareAll([2, 3, 4])
print(result)
